head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldods17001";
scwin.chkboxAllChk = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_pageCount", fn: function(){ return ((dma_page.get("pageCount") ?? (() => { throw new Error("unresolved:" + "page.pageCount"); })())!==0); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_32", entity: "dlt_bzIdList", countIds: [], cells: [{ childId: "ipt_usrStatIdArr", fn: function (v, i) { return String(v("sprtBzDtlId")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return " onclick=\"chkboxAllChk()\">" + String(dlt_bzIdList.getCellData(0, "sprtBzDtlNm")); } },
        { childId: "__rb1", fn: function () { return "전체 " + String(dma_page.get("total")) + "건 [0" + String(dma_usradmForm.get("pageIndex")) + "/" + String(dma_page.get("pageCount")) + " 페이지]"; } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

// [A] 초기 목록 미해결 — jldods17001: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.chkboxAllChk = chkboxAllChk;
        scwin.init_fillGen();
        scwin.init_rowCopy();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldods17001.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name input_37_onclick
 * @description 「검색」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.input_37_onclick = async function(e){
    try {
        await scwin.search(1)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods17001.input_37_onclick' }); }
};

/**
 * @method
 * @name slc_pageSize_onchange
 * @description slc_pageSize 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.slc_pageSize_onchange = async function(e){
    try {
        await scwin.search(1);

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods17001.slc_pageSize_onchange' }); }
};

/**
 * @method
 * @name grd_userList_oncellclick
 * @description grd_userList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_userList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_userList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_userList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        scwin.detail(r["integUsrId"], r["usrStatId"], r["isurCd"], r["chrgTpCd"], r["disclsBzChrgAssgnDd"], r["seq"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_userList.oncellclick' });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name __on_enter_1_ipt_corpusrnm
 * @description on enter 1 ipt corpusrnm 처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.__on_enter_1_ipt_corpusrnm = async function(e){
    try {
        const ev = e;
        if(($c.util.getKeyCode(ev))===13){ await scwin.search() }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods17001.__on_enter_1_ipt_corpUsrNm' }); }
};

/**
 * @method
 * @name __on_enter_2_ipt_usrbelngdepnm
 * @description on enter 2 ipt usrbelngdepnm 처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.__on_enter_2_ipt_usrbelngdepnm = async function(e){
    try {
        const ev = e;
        if(($c.util.getKeyCode(ev))===13){ await scwin.search() }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods17001.__on_enter_2_ipt_usrBelngDepNm' }); }
};

/**
 * @method
 * @name grd_userList_fmt_column1
 * @description grd user List fmt column1 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_userList_fmt_column1 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_userList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "no") ?? '') : '');
        if (v !== '0') { return (console.error('[sdd] 미실현 라벨 갈래: column1 (expression)'), String(data ?? '')); }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_userList.column1" }); return String(data ?? ''); }
};

/**
 * @method
 * @name detail
 * @description detail 처리
 * @param {String} ipt_integUsrId ipt_integUsrId
 * @param {String} ipt_usrStatId ipt_usrStatId
 * @param {String} ipt_isurCd ipt_isurCd
 * @param {String} ipt_chrgTpCd ipt_chrgTpCd
 * @param {String} ipt_disclsBzChrgAssgnDd ipt_disclsBzChrgAssgnDd
 * @param {*} ipt_seq ipt_seq
 * @returns {void}
 * @hidden N
 */
scwin.detail = function (ipt_integUsrId, ipt_usrStatId, ipt_isurCd, ipt_chrgTpCd, ipt_disclsBzChrgAssgnDd, ipt_seq) {
    $('#ipt_integUsrId', $('#searchForm')).val(ipt_integUsrId);
    $('#ipt_usrStatId', $('#searchForm')).val(ipt_usrStatId);
    $('#ipt_isurCd', $('#searchForm')).val(ipt_isurCd);
    $('#ipt_chrgTpCd', $('#searchForm')).val(ipt_chrgTpCd);
    $('#ipt_disclsBzChrgAssgnDd', $('#searchForm')).val(ipt_disclsBzChrgAssgnDd);
    $('#ipt_seq', $('#searchForm')).val(ipt_seq);
    if (ipt_integUsrId === "-") {
        $('#ipt_usrStatId', $('#searchForm')).val("RETN");
        $('#ipt_SCREN_ID', $('#searchForm')).val("/jldods17010/jldods17010.xml");
    } else {
        if (ipt_usrStatId === "APPL") {
            $('#ipt_SCREN_ID', $('#searchForm')).val("/jldods17011/jldods17011.xml");
        } else {
            if (ipt_usrStatId === "NORM") {
                $('#ipt_SCREN_ID', $('#searchForm')).val("/jldods17012/jldods17012.xml");
            } else {
                if (ipt_usrStatId === "STOP") {
                    $('#ipt_SCREN_ID', $('#searchForm')).val("/jldods17013/jldods17013.xml");
                } else {
                    $('#ipt_SCREN_ID', $('#searchForm')).val("/jldods17010/jldods17010.xml");
                }
            }
        }
    }
    $('#ipt_method', $('#searchForm')).val("readUserDetail");
    $('#searchForm').submit();
};

/**
 * @method
 * @name search
 * @description search 처리
 * @param {*} ipt_pageIndex ipt_pageIndex
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function (ipt_pageIndex) {
    if (ipt_pageIndex) {
        $('#ipt_pageIndex', $('#searchForm')).val(ipt_pageIndex);
    }
    if ($('#ipt_startDate', $('#searchForm')).val() !== "" && !$c.date.isDate($('#ipt_startDate', $('#searchForm')).val())) {
        await alertE("시작일자 형식이 틀립니다.");
        return;
    }
    if ($('#ipt_endDate', $('#searchForm')).val() !== "" && !$c.date.isDate($('#ipt_endDate', $('#searchForm')).val())) {
        await alertE("종료일자 형식이 틀립니다.");
        return;
    }
    if ($('#ipt_startDate', $('#searchForm')).val() !== "" && $('#ipt_endDate', $('#searchForm')).val() !== "" && $('#ipt_startDate', $('#searchForm')).val() > $('#ipt_endDate', $('#searchForm')).val()) {
        await alertE("시작일자는 종료일자 이전 이여야 합니다.");
        return;
    }
    blockLoading();
    $('#ipt_SCREN_ID', $('#searchForm')).val("/jldods17001/jldods17001.xml");
    $('#ipt_method', $('#searchForm')).val("readUserList");
    $('#searchForm').submit();
};

/**
 * @method
 * @name chkboxAll
 * @description chkbox All 처리
 * @param {*} allChecked allChecked
 * @returns {void}
 * @hidden N
 */
scwin.chkboxAll = function (allChecked) {
    if (allChecked) {
        $("input[name=usrStatIdArr]", $('#searchForm')).prop("checked", true);
    } else {
        $("input[name=usrStatIdArr]", $('#searchForm')).prop("checked", false);
    }
};

function chkboxAllChk() {
    let cnt = 0;
    const totCnt = $("input[name=usrStatIdArr]", $('#searchForm')).length - 1;
    $("input[name=usrStatIdArr]", $('#searchForm')).each(function() {
            if (this.value !== "ALL" && this.checked) {
                cnt++;
            }
    });
    if (cnt === totCnt) {
        $("input[id=ipt_usrStatIdAll]", $('#searchForm')).prop("checked", true);
    } else {
        $("input[id=ipt_usrStatIdAll]", $('#searchForm')).prop("checked", false);
    }
}

/**
 * @method
 * @name alertE
 * @description alert E 처리
 * @param {String} msg 항목명
 * @param {*} callback callback
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.alertE = async function (msg, callback) {
    // as-is 는 화면 안 #pAlertText/#divAlertMsg 를 만졌다 — 엔진 프레임 접두 때문에
    // 그 선택자는 어디서도 못 찾는다. 표준 알림으로 낸다(메시지가 사라지지 않게).
    await $c.win.alert(msg);
    if (typeof callback === 'function') { await callback(); }
};

async function alertE(msg, callback) { return await scwin.alertE(msg, callback); }

/**
 * @method
 * @name krxpage_pagenavigator_99_onclick
 * @description krxpage_pagenavigator_99 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_99_onclick = async function (index) {
    try {
        const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index;
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldods17001.krxpage_pagenavigator_99_onclick" });
    }
};
